--[=[
	@class DebugOptions

	开发选项模块
]=]
local DebugOptions = {}
DebugOptions.__index = DebugOptions

-- 获取储存开发选项的目录，放在 'ReplicatedStorage' 下面
DebugOptions.OptionsFolder = "__developer"

local localUserId = nil

-- 服务端，等待0.1秒，让用户登陆，找到第一个id
if game["Run Service"]:IsServer() and game["Run Service"]:IsStudio() then
	for i = 1, 20, 1 do
		task.wait(0.1)
		localUserId = game.Players:GetPlayers()[1] and game.Players:GetPlayers()[1].UserId or nil
		if localUserId then
			break
		end
	end
elseif game["Run Service"]:isClient() then
	localUserId = game.Players.LocalPlayer.UserId
end

-- 获取储存开发选项的目录，如果不存在则创建
function DebugOptions.GetDevFolder(userId)
	local folderDev = game.ReplicatedStorage:FindFirstChild(DebugOptions.OptionsFolder)
	if not folderDev then
		folderDev = Instance.new("Folder", game.ReplicatedStorage)
		folderDev.Name = DebugOptions.OptionsFolder
	end

	local folderUser = folderDev:FindFirstChild(tostring(userId))
	if not folderUser then
		folderUser = Instance.new("Folder", folderDev)
		folderUser.Name = tostring(userId)
	end

	return folderUser
end

--[=[
	是否允许指定选项

	上线后的游戏返回 false

	未找到值返回 false


	@param key string -- 指定选项的key
]=]
function DebugOptions.IsEnable(key: string): boolean
	if not game["Run Service"]:IsStudio() then
		return false
	end

	local folderUser = DebugOptions.GetDevFolder(localUserId)

	local value = folderUser:FindFirstChild(key)
	-- assert value type is BoolValue
	if value and value:IsA("BoolValue") then
		return value.Value
	else
		return false
	end
end

--[=[
	获取指定选项的值

	上线后的游戏返回 nil

	未找到值返回 nil

	@param key string -- 指定选项的key
]=]
function DebugOptions.GetValue(key: string): boolean
	if not game["Run Service"]:IsStudio() then
		return nil
	end

	local folderUser = DebugOptions.GetDevFolder(localUserId)

	local value = folderUser:FindFirstChild(key)
	if value then
		local success, result = pcall(function()
			return value.Value
		end)
		if success then
			return result
		end
	end
	return nil
end

-- 获取调试用户ID
DebugOptions.GetUserId = function()
	return localUserId
end

DebugOptions.IsClientDev = DebugOptions.IsEnable("悟空客户端调试开关")

DebugOptions.DevUserId = DebugOptions.GetUserId()

return DebugOptions
